head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _2 : drillTo @param rowIndex 의 MultiLine caveat 전용 샘플.
//     한 데이터 레코드(rowIndex N)를 2개의 Line(TR)으로 표시(MultiLine).
//       Line1 : name(drilldown 펼침) | amount
//       Line2 : memo(일반 text 셀, colspan 병합)  ← drilldown 없음
//     · drillTo(rowIndex) 실행 후 "그리드 상태"로 검증(_1 과 동일 방식) :
//         (1) 표시 Row 목록 — 조상(부모)이 펼쳐져 기준 Row 가 화면에 표시되는지.
//         (2) getOpenStatus(rowIndex) — 기준 Row 자신의 자식은 펼치지 않음(false).
//       MultiLine caveat 입증 : 그리드 자체가 MultiLine(레코드당 2 Line) 구성인데도
//       단일 rowIndex 로 위 그리드 상태가 정상 변함(각 Line 이 같은 rowIndex 로 처리됨).
scwin.tData = {
    "description" : "[gridView > M > drillTo]<br/>DrillDown 이 적용되었을때 특정 Row 부터 최상위 부모 Row 까지 모두 펼칩니다.",
    "validation" : [
        "Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 기본 선택을 접힌 자식 Row(1)로 지정 → 첫 클릭에 펼침이 보이도록 (정적 select1 은 onpageload setValue 필요)
    par_rowIndex.setValue("1");
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - DrillDown 트리(inputType="drilldown" + depthColumn) + MultiLine(레코드당 2 Line) 그리드 구성
//    · header / gBody 각각 <w2:row> 2개 → 레코드당 2 Line.
//      Line1 : name(drilldown 펼침) / amount   ← drilldown 셀은 여기 1개뿐
//      Line2 : memo(일반 text, colspan 병합)    ← drilldown 없음
//  - drilldownRealRowIndexAll="true" : drillTo(rowIndex) 의 rowIndex 를 바인딩 DataList 기준으로 처리
//  - showDepth="1" → 초기엔 depth1(부모)만 표시, 자식은 접힘
//  - 데이터(DataList idx): 영업본부(0) > 영업1팀(1), 개발본부(2) > 개발1팀(3)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] drilldown 트리 + MultiLine(레코드당 2 Line: 이름(펼침)/메모). rowIndex=DataList 기준. 데이터: 영업본부(0)>영업1팀(1), 개발본부(2)>개발1팀(3). 초기엔 부모(0/2)만 표시.\n[절차] par_rowIndex 선택 후 drillTo 클릭(기본 1).\n[확인] 표시 Row 목록에 기준 Row 포함(조상 펼침) + getOpenStatus=false(자식 미펼침). MultiLine(레코드당 2 Line)이어도 단일 rowIndex 로 그리드 상태가 정상 변함."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (부모=1, 자식=2)
    //  - memo : 레코드의 두번째 Line 표시
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "영업본부", "amount": 100, "memo": "영업본부 memo Line", "depth": 1 },
        { "name": "영업1팀", "amount": 110, "memo": "영업1팀 memo Line",  "depth": 2 },
        { "name": "개발본부", "amount": 200, "memo": "개발본부 memo Line", "depth": 1 },
        { "name": "개발1팀", "amount": 210, "memo": "개발1팀 memo Line",  "depth": 2 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // DrillDown + MultiLine : header / gBody 각각 <w2:row> 2개 (레코드당 2 Line)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' drilldownRealRowIndexAll="true" dataList="data:dlt_bind" rowNumVisible="true" defaultCellHeight="30" id="" style="width:560px;height:420px;">';
    strTarget += '<w2:caption style="" id="caption1" value="drillTo (DrillDown + MultiLine) 테스트 그리드"></w2:caption>';
    // Header : Line1(이름/금액) / Line2(메모)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="300" style="" inputType="text" id="hcol_name" value="이름(drilldown 펼침)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_amount" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="*" colspan="2" style="" inputType="text" id="hcol_memo" value="메모(drilldown 없음)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1(name drilldown, amount) / Line2(memo 일반 text) → 레코드당 2 TR Line
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="300" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="*" colspan="2" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// 현재 화면에 표시되는 Row 목록 (display 순회 → getRealRowIndex → DataList name)
//  - MultiLine 이어도 getRowCount 는 "레코드(논리 Row)" 수를 반환하므로 레코드 단위로 순회된다.
scwin._getVisibleRowText = function () {
    let names = [];
    for (let i = 0; i < target1.getRowCount(); i++) {
        let real = target1.getRealRowIndex(i);
        names.push(real + ":" + dlt_bind.getCellData(real, "name"));
    }
    return "(" + names.length + ") " + names.join(", ");
};

// 특정 DataList rowIndex 가 현재 화면 표시 목록에 포함되는지 (조상 펼침 확인용)
scwin._isRowVisible = function (rowIndex) {
    for (let i = 0; i < target1.getRowCount(); i++) {
        if (target1.getRealRowIndex(i) === rowIndex) return true;
    }
    return false;
};



// [drillTo] : par_rowIndex(DataList 기준) 부터 최상위 부모까지 모두 펼친 뒤 "그리드 상태"로 검증
//  - (1) 표시 Row 목록 : drillTo 후 기준 Row 가 표시 목록에 포함되면 조상(부모)이 모두 펼쳐진 것
//  - (2) getOpenStatus(rowIndex) : 기준 Row 자신의 자식은 펼치지 않음(false)
//  - MultiLine caveat : 그리드 자체가 MultiLine(레코드당 2 Line) 구성인데도 단일 rowIndex 로
//    위 그리드 상태가 정상 변함(각 Line 이 같은 rowIndex 로 처리됨을 상태 변화로 입증)
scwin.btn_drillTo_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    let beforeVis = scwin._getVisibleRowText();

    target1.drillTo(rowIndex);

    let afterVis = scwin._getVisibleRowText();
    let baseName = dlt_bind.getCellData(rowIndex, "name");
    let shown = scwin._isRowVisible(rowIndex);

    b.setReturnValue("drillTo(" + rowIndex + ") 표시 Row : " + afterVis + (beforeVis === afterVis ? " (변화 없음 : Root 라 펼칠 부모 없음)" : " (부모 펼침)"));
    b.setReturnValue("기준 Row(" + rowIndex + ":" + baseName + ") 화면 표시 : " + shown + " / getOpenStatus(" + rowIndex + ") : " + target1.getOpenStatus(rowIndex) + " (자식 미펼침)");
};
